const tabId = 730410078;
const found = await browserjs(tabId, () => {
  function searchShadow(root) {
    let results = [];
    const elements = root.querySelectorAll('*');
    for (const el of elements) {
      if (el.textContent && el.textContent.includes("Shop cars in your budget")) {
        results.push({
          tagName: el.tagName,
          outerHTML: el.outerHTML.slice(0, 300),
          href: el.href || el.getAttribute('href'),
          target: el.target || el.getAttribute('target')
        });
      }
      if (el.shadowRoot) {
        results = results.concat(searchShadow(el.shadowRoot));
      }
    }
    return results;
  }
  return searchShadow(document);
});
console.log("Found:", JSON.stringify(found, null, 2));

